head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// Body 의 첫 Column 표시값을 읽어 정렬 여부를 판단할 수 있게 한다.
scwin.readBody = function () {
    var arrRow = document.querySelectorAll("#mf_target1_body_table tr");
    var arrText = [];
    for (var i = 0; i < arrRow.length; i++) {
        var objCell = document.getElementById("mf_target1_cell_" + i + "_0");
        if (objCell !== null) { arrText.push(objCell.textContent.trim()); }
    }
    return arrText.join(",");
};

// Header Cell 에 정렬 가능 표시 클래스(w2grid_head_sortable)가 붙어 있는지 확인한다.
scwin.hasSortableClass = function (strId) {
    var objTh = document.getElementById(strId);
    if (objTh === null) { return "요소 없음"; }
    return (objTh.className.indexOf("w2grid_head_sortable") >= 0) ? "있음" : "없음";
};

scwin.btn_check_onclick = function (e) {
    var objTarget = $p.getComponentById("target1");
    var arrSortable = objTarget.getSortableArr();

    scwin.setReturnValue("=====RowNum / RowStatus Column 의 정렬 가능 여부=====");
    scwin.setReturnValue("getSortableArr() : [" + arrSortable.join(",") + "]");
    scwin.setReturnValue("    [0] RowNum    : " + arrSortable[0]);
    scwin.setReturnValue("    [1] RowStatus : " + arrSortable[1]);
    scwin.setReturnValue("    [2] col1(일반 Column, sortable=true) : " + arrSortable[2]);
    scwin.setReturnValue("");
    scwin.setReturnValue("Header Cell 의 w2grid_head_sortable 클래스");
    scwin.setReturnValue("    RowNum    : " + scwin.hasSortableClass("mf_target1__headerRowNumber"));
    scwin.setReturnValue("    RowStatus : " + scwin.hasSortableClass("mf_target1__headerRowStatus"));
    scwin.setReturnValue("    col1      : " + scwin.hasSortableClass("mf_target1_hcol1"));
    scwin.setReturnValue("");
    scwin.setReturnValue("----- 판정 -----");
    if (arrSortable[0] === false && arrSortable[1] === false) {
        scwin.setReturnValue("RowNum / RowStatus 가 정렬 불가(false)로 보고된다");
    } else {
        scwin.setReturnValue("RowNum / RowStatus 가 정렬 가능(true)으로 보고된다 — 실제로는 정렬되지 않는 Column 이다");
    }
    scwin.setReturnValue("");
};

// RowNum Header 를 클릭해 실제로 정렬이 일어나는지 확인한다.
scwin.btn_sort_onclick = function (e) {
    var strBefore = scwin.readBody();
    var objTh = document.getElementById("mf_target1__headerRowNumber");
    if (objTh !== null) { objTh.click(); }

    setTimeout(function () {
        var strAfter = scwin.readBody();
        scwin.setReturnValue("=====RowNum Header 클릭 시 실제 정렬 여부=====");
        scwin.setReturnValue("    클릭 전 col1 : " + strBefore);
        scwin.setReturnValue("    클릭 후 col1 : " + strAfter);
        scwin.setReturnValue("    정렬 발생 : " + ((strBefore === strAfter) ? "없음" : "있음"));
        scwin.setReturnValue("");
    }, 500);
};
